<span class="line">        <span class="token class-name">NotificationMessage</span> message <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">NotificationMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
